import itertools

def solve():
    nums = [6, 7, 8, 3, 5, 6, 5, 9, 4, 4, 9, 2, 8, 5, 7, 3, 3, 1, 6, 6, 6, 8, 3, 5, 2]
    grid = [[0, 7, 0, 1, 0, 0], [6, 0, 0, 0, 0, 2], [0, 0, 0, 8, 4, 0], [0, 0, 6, 0, 0, 0], [0, 0, 3, 0, 2, 0], [0, 0, 4, 0, 2, 0]]
    row_targets = [22, 36, 33, 33, 24, 28]
    col_targets = [27, 43, 34, 29, 22, 21]
    row_zeros = [[c for c in range(6) if grid[r][c] == 0] for r in range(6)]
    row_needed = [row_targets[r] - sum(grid[r]) for r in range(6)]

    def get_row_combinations(needed_sum, num_count, available_counts):
        results = []
        elements = sorted(available_counts.keys(), reverse=True)
        def backtrack_comb(idx, current_sum, current_list):
            if len(current_list) == num_count:
                if current_sum == needed_sum: results.append(list(current_list))
                return
            if idx == len(elements): return
            val = elements[idx]
            for i in range(min(num_count - len(current_list), available_counts[val]) + 1):
                if current_sum + i * val > needed_sum: break
                backtrack_comb(idx + 1, current_sum + i * val, current_list + [val]*i)
        backtrack_comb(0, 0, [])
        return results

    col_sums = [sum(grid[r][c] for r in range(6)) for c in range(6)]
    counts = Counter(nums)

    def solve_rows(r, current_counts):
        if r == 6: return [row[:] for row in grid] if all(col_sums[c] == col_targets[c] for c in range(6)) else None
        combos = get_row_combinations(row_needed[r], len(row_zeros[r]), current_counts)
        for combo in combos:
            for p in set(itertools.permutations(combo)):
                valid_p = True
                for i, c in enumerate(row_zeros[r]):
                    grid[r][c] = p[i]
                    col_sums[c] += p[i]
                    if col_sums[c] > col_targets[c]: valid_p = False
                if valid_p:
                    new_counts = current_counts.copy()
                    for val in p: new_counts[val] -= 1
                    res = solve_rows(r + 1, new_counts)
                    if res: return res
                for i, c in enumerate(row_zeros[r]):
                    col_sums[c] -= p[i]
                    grid[r][c] = 0
        return None

    final_grid = solve_rows(0, counts)
    if final_grid: return final_grid

res = solve()
if res:
    for row in res:
        print(' '.join(map(str, row)))"}

